const body = $json.body ?? $json;
return [{
  json: {
    message: String(body.message ?? '').trim().toLowerCase(),
    language: String(body.language ?? 'es').trim().toLowerCase()
  }
}];

const { message, language } = $json;
const faq = [
  {
    key: 'shipping',
    terms: ['envio', 'envío', 'shipping', 'delivery'],
    es: 'El tiempo y costo de envío dependen de la zona. Confirma la ciudad para consultar la información aprobada.',
    en: 'Shipping time and cost depend on the destination. Confirm the city to check the approved information.'
  },
  {
    key: 'materials',
    terms: ['material', 'oro', 'gold', 'acero', 'steel'],
    es: 'Consulta la ficha oficial del producto antes de confirmar el material. No se deben inventar especificaciones.',
    en: 'Check the official product record before confirming materials. Never invent specifications.'
  },
  {
    key: 'human',
    terms: ['persona', 'humano', 'agent', 'human'],
    es: 'La conversación debe transferirse a una persona.',
    en: 'The conversation should be transferred to a person.'
  }
];

const match = faq.find(item => item.terms.some(term => message.includes(term)));
if (!message) {
  return [{ json: { ok: false, category: 'invalid', reply: 'A message is required.', escalate: false } }];
}
if (!match) {
  return [{
    json: {
      ok: true,
      category: 'unknown',
      reply: language === 'en'
        ? 'I do not have an approved answer. I will route this to a person.'
        : 'No tengo una respuesta aprobada. Transferiré la consulta a una persona.',
      escalate: true
    }
  }];
}
return [{
  json: {
    ok: true,
    category: match.key,
    reply: language === 'en' ? match.en : match.es,
    escalate: match.key === 'human'
  }
}];
